/**
 * Trailing debounce with optional maxWait (burst safety valve).
 * Exported for unit testing.
 */
export function debounce(fn: () => void, wait: number, maxWait?: number): () => void {
  let timer: ReturnType<typeof setTimeout>|undefined;
  let maxTimer: ReturnType<typeof setTimeout>|undefined;
  const fire=()=>{clearTimeout(timer);clearTimeout(maxTimer);timer=undefined;maxTimer=undefined;fn();};
  return ()=>{
    clearTimeout(timer);
    timer=setTimeout(fire,wait);
    if(maxWait!==undefined&&!maxTimer)maxTimer=setTimeout(fire,maxWait);
  };
}

