  useEffect(()=>{let live=true;const projectId=selectedProject;const load=async()=>{if(!projectId){setCliUsage(undefined);setCliUsageProjectId(undefined);setCliUsageLoading(false);setCliUsageError(false);return;}const request=++cliUsageRequest.current;if(cliUsageLoadingForRef.current!==projectId){setCliUsage(undefined);cliUsageLoadingForRef.current=projectId;}setCliUsageLoading(true);setCliUsageError(false);try{const value=await api<CliUsage>(`/api/projects/${encodeURIComponent(projectId)}/usage`);if(live&&request===cliUsageRequest.current){setCliUsage(value);setCliUsageProjectId(projectId);setCliUsageError(false);}}catch{if(live&&request===cliUsageRequest.current){setCliUsageProjectId(projectId);setCliUsageError(true);}}finally{if(live&&request===cliUsageRequest.current)setCliUsageLoading(false);}};void load();const timer=window.setInterval(load,60000);return()=>{live=false;clearInterval(timer);};},[selectedProject]);
